#include <vector>
#include <omp.h>

void prefixSum(std::vector<double> const& x, std::vector<double> &output) {
    const std::size_t n = x.size();
    output.assign(n, 0.0);
    if (n == 0) return;

    int P = 1;
#pragma omp parallel
    {
#pragma omp single
        { P = omp_get_num_threads(); }
    }

    std::vector<double> blockSums(static_cast<std::size_t>(P) + 1u, 0.0); // blockSums[t] = sum of block t

#pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int nt  = omp_get_num_threads();

        // Use the actual number of threads participating in this region.
        // Only one thread updates blockSums size logically via nt; we keep vector sized to initial P.
        const std::size_t t = static_cast<std::size_t>(tid);
        const std::size_t T = static_cast<std::size_t>(nt);

        const std::size_t begin = (n * t) / T;
        const std::size_t end   = (n * (t + 1)) / T;

        // 1) Local prefix within each block; also compute total sum of block.
        double running = 0.0;
        for (std::size_t i = begin; i < end; ++i) {
            running += x[i];
            output[i] = running;
        }

        // Each thread writes its own block sum exactly once.
        blockSums[t] = running;

#pragma omp barrier

        // 2) Single thread computes offsets (exclusive prefix over block sums).
#pragma omp single
        {
            double offset = 0.0;
            for (std::size_t k = 0; k < T; ++k) {
                const double s = blockSums[k];
                blockSums[k] = offset; // reuse as offset for block k
                offset += s;
            }
            blockSums[T] = offset; // optional total sum
        }

#pragma omp barrier

        // 3) Add block offset to each element in block.
        const double offset = blockSums[t];
        for (std::size_t i = begin; i < end; ++i) {
            output[i] += offset;
        }
    }
}
